INSERT INTO quizzes (id, teacher_id, title, description, subject, grade_level, topic, questions, is_published, published_at) VALUES
('60b185ec-0474-49ae-864d-2e0d656f8791', '21feff02-016d-46e2-bb9d-c27495133b1b', '1. óra: Az év bevezetése, ismétlés, játékos bevezető', 'Éves munkarend, elvárások, játékos feladatok az éves munka elkezdéséhez.', 'Matematika', '6. osztály', 'Év eleji ismétlés, diagnosztika', '[{"id": "818c8f61-0ef7-489a-b158-63d5217c6289", "text": "Mi az éves matematika munka legfőbb célja?", "type": "multiple-choice", "options": [{"id": "4a1e914a-4a30-42e9-be81-3c531fd32bb3", "text": "A gondolkodási képesség és matematikai tudás fejlesztése", "isCorrect": true}, {"id": "a6b1a73a-02ea-4866-adac-9e06204fc771", "text": "A könyvek visszagyűjtése", "isCorrect": false}, {"id": "f9f0bf80-6f1c-45aa-97f3-2b6be85e16bb", "text": "Csak a házi feladat írása", "isCorrect": false}, {"id": "6709ed9f-fb64-4966-9ba3-79c5766a6822", "text": "A számonkérések elkerülése", "isCorrect": false}], "timeLimit": 15}, {"id": "e163b148-5c77-4953-8e85-0dcb75ce9dcf", "text": "A játékos matematikai feladatok segítik a tanulásra való ráhangolódást.", "type": "true-false", "options": [{"id": "6d2d7571-0bab-4818-b7bb-f05c0f2f954d", "text": "Igaz", "isCorrect": true}, {"id": "0f7daff6-c378-4141-ba69-ad27cf5e5e88", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3259b50d-57db-421e-a5be-8e2b5cb6e9ff", "text": "Hány hétből áll egy átlagos magyar tanév?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "36"}, {"id": "98bff86d-d660-4e89-ada4-b3848a2ca7aa", "text": "Melyik állítás ír le helyes tanulási magatartást?", "type": "multiple-choice", "options": [{"id": "ef262eca-242c-4ab0-a724-34e434b62f7d", "text": "Rendszeres felkészülés és a hibák megbeszélése", "isCorrect": true}, {"id": "034c9100-6842-4813-8aa5-9e0362e32e13", "text": "Minden feladat feladása az első hibánál", "isCorrect": false}, {"id": "68f0f113-2463-42fc-ae8b-07de5b35eabe", "text": "A füzet otthon hagyása", "isCorrect": false}, {"id": "8f81498a-c0e0-4185-99b4-d3172e07038f", "text": "Másolás a padtárstól", "isCorrect": false}], "timeLimit": 15}, {"id": "c63c06ac-98e8-46d9-9ac5-4120f84ac835", "text": "Mennyi a 25 + 75 összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "8b829c66-c7b2-4ad6-ae86-810dc9a55c52", "text": "A matematikai órákon a csoportmunka során fontos a kooperáció és egymás segítése.", "type": "true-false", "options": [{"id": "9789ed03-ccff-4918-a81f-6f88966af3af", "text": "Igaz", "isCorrect": true}, {"id": "ef4b8464-68b6-48c2-b478-6cbc3b98d7be", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3e01da0d-85b8-44c6-884d-42181e029dda", "text": "Mennyi 8 * 9?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "72"}]'::jsonb, true, NOW()),
('35fa41fc-7060-4ef0-a8ee-d15b4c08fcf5', '21feff02-016d-46e2-bb9d-c27495133b1b', '2. óra: Játékok', 'Játékszabályok, stratégiák, logikai gondolkodás páros és csoportmunkában.', 'Matematika', '6. osztály', 'Év eleji ismétlés, diagnosztika', '[{"id": "b3bf9725-2147-49d0-95e4-9ca1fdb4335d", "text": "Mi a stratégiai játékok lényege?", "type": "multiple-choice", "options": [{"id": "daedebd4-bd6a-46c1-9355-bf00be8681d4", "text": "Előre megtervezett lépésekkel a cél elérése", "isCorrect": true}, {"id": "b45bf290-47e2-4038-be24-99f32de9f0a3", "text": "Kizárólag a szerencsére hagyatkozás", "isCorrect": false}, {"id": "44f7d75a-e2cf-4faf-9a5c-0c6e51c612a1", "text": "Kockadobás számolás nélkül", "isCorrect": false}, {"id": "4e454439-9334-4e84-83f1-f71c566ceed4", "text": "A szabályok figyelmen kívül hagyása", "isCorrect": false}], "timeLimit": 15}, {"id": "2249802a-f602-4ef2-b2bb-8f1114d35774", "text": "A páros és csoportmunka során fontos a csapattársak véleményének meghallgatása.", "type": "true-false", "options": [{"id": "89bcaaf9-af2b-49ce-b701-282e376c0216", "text": "Igaz", "isCorrect": true}, {"id": "31b983b7-4529-47af-83cf-1d1fef63c8ff", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "0ac15e77-ce39-4452-ab75-ad8e4c7b8d00", "text": "Hány mezőből áll egy klasszikus 8x8-as sakktábla?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "64"}, {"id": "e6fbfd48-6a05-49f9-919c-c12c2e511d5c", "text": "Melyik játék fejleszti kifejezetten a logikai gondolkodást és a számolást?", "type": "multiple-choice", "options": [{"id": "84b1902f-f391-4758-9411-45ebc5a2b2c8", "text": "Sudoku", "isCorrect": true}, {"id": "89825af1-c161-4355-813c-bfde75130be3", "text": "Fócsoport", "isCorrect": false}, {"id": "af97a23a-ba44-48fb-8624-3fb6c2862d57", "text": "Futóverseny", "isCorrect": false}, {"id": "93942f8a-48bd-4675-9f2b-a819b3437e0f", "text": "Kő-papír-olló", "isCorrect": false}], "timeLimit": 15}, {"id": "d248f4a5-f58e-4aca-b4a8-e04f230b9be5", "text": "A bűvös négyzetben minden sor, oszlop és átló összege megegyezik.", "type": "true-false", "options": [{"id": "de38806b-3500-4a14-938a-072b1b6d3684", "text": "Igaz", "isCorrect": true}, {"id": "173dadf5-05d7-408a-b26c-54b27bba8ccc", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "2249df38-1f4d-4ea7-8d19-bf1928a5c5c0", "text": "Mennyi az 1, 2, 3, 4, 5 számok összege?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "15"}, {"id": "a44500fe-a6dd-4fa0-9b08-bbfd72312aa0", "text": "A szabályok betartása elengedhetetlen a fair play játékban.", "type": "true-false", "options": [{"id": "13f044fd-c542-4e4f-a648-0307e46aa0fe", "text": "Igaz", "isCorrect": true}, {"id": "80e5b4f0-2b7e-496b-9bb0-3e89516b753b", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('07f825ba-1bf8-46d0-86a0-e361aedcdb48', '21feff02-016d-46e2-bb9d-c27495133b1b', '3. óra: Év eleji diagnosztikus felmérés', 'Az 5. osztályban tanult ismeretek felmérése, tudásszint diagnosztizálása.', 'Matematika', '6. osztály', 'Év eleji ismétlés, diagnosztika', '[{"id": "839d6ced-f10e-47b4-8d2f-4a5ec6a48d57", "text": "1. Mennyi (-12) + 5?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-7"}, {"id": "f17e6a35-1093-49dd-bb9f-2e22a279e035", "text": "2. Mennyi 3/4 + 1/4?", "type": "multiple-choice", "options": [{"id": "370bbc99-ce32-4083-b9d7-7f2e301ad5f7", "text": "1 egész (4/4)", "isCorrect": true}, {"id": "d885eadc-ada7-48ce-80cb-96da3595e954", "text": "2/4", "isCorrect": false}, {"id": "2a7f9553-8deb-4b72-b48f-22cc25fc4cc7", "text": "4/8", "isCorrect": false}, {"id": "939e3c46-3eb6-43b5-9a5e-9841ce4eb3be", "text": "3/8", "isCorrect": false}], "timeLimit": 15}, {"id": "40a7110b-38b9-4cc2-9b51-ab8daa88c034", "text": "3. Mennyi a 4 cm oldalú négyzet kerülete? (cm-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "74878e28-021b-41aa-91fe-2fe7fc63d6a1", "text": "4. Mennyi a 4 cm oldalú négyzet területe? (cm²-ben)", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "16"}, {"id": "2a14ef5d-4322-47d6-bbe5-38f67393bbe7", "text": "5. Hány gramm 2,5 kg?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2500"}, {"id": "d82ceb42-23f8-4dc5-be95-3a7988c59721", "text": "6. A negatív számok a nullától balra találhatók a számegyenesen.", "type": "true-false", "options": [{"id": "3e679fab-42b2-4f53-90d6-2a9ef0446d72", "text": "Igaz", "isCorrect": true}, {"id": "702fd6a0-2fe7-401b-88a0-eb7975895cdf", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3dc54ee9-6f87-484f-b92b-29b160a1743c", "text": "7. Hány perc 1 és fél óra?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "90"}, {"id": "1ab2f4ee-3dae-4442-b4c0-3cd427bc43e6", "text": "8. Mennyi 0,5 + 0,7?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "1.2"}, {"id": "4b77fed2-f0bb-4050-82b0-146ccc925407", "text": "9. A derékszögű háromszögnek van egy 90°-os szöge.", "type": "true-false", "options": [{"id": "de837d8a-6e66-4125-a43f-d4e89fdafa36", "text": "Igaz", "isCorrect": true}, {"id": "99672daf-6521-4b72-995e-56e1f6249c3e", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "a65fd484-3774-4e33-8000-3ac15b0037bf", "text": "10. Hány csúcsa van a kockának?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "8"}]'::jsonb, true, NOW()),
('17467bb4-0905-4618-8c9a-d208533db60f', '21feff02-016d-46e2-bb9d-c27495133b1b', '4. óra: Műveletek az egész számok körében', 'Mit tanultunk ötödik osztályban? A felmérés tapasztalatainak feldolgozása, hibajavítás.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "b0c8ec84-d003-424b-8e78-d21c0f5643e0", "text": "Mennyi (-8) + (+15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "7"}, {"id": "f7416af9-ace0-40d9-af31-0e34dc668814", "text": "Mennyi (-6) - (+4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-10"}, {"id": "45796078-78b1-4ca7-a77f-c1081a39dba1", "text": "Az ellentett számok összege mindig 0.", "type": "true-false", "options": [{"id": "c59ed09f-5b31-4c6a-b567-47ab93698093", "text": "Igaz", "isCorrect": true}, {"id": "bf371a45-efce-4d47-9115-5ff9c0919e2f", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "ce87ff5a-358e-4c40-9136-a76e91723163", "text": "Mennyi |-25| (a -25 abszolút értéke)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "25"}, {"id": "b436b930-4275-44b5-9772-681b79d277ec", "text": "Melyik szám nagyobb: -15 vagy -8?", "type": "multiple-choice", "options": [{"id": "ab40ef94-f4c3-4cd5-978f-5354463ae4b7", "text": "-8", "isCorrect": true}, {"id": "9f75c6b5-d949-4947-bae7-bd34271cfa06", "text": "-15", "isCorrect": false}, {"id": "3fe533df-9394-4d1b-a7f5-ccca4d43c6b6", "text": "Egyenlőek", "isCorrect": false}, {"id": "70c14332-bff3-47b7-b331-9c31e950d5b7", "text": "Nem összehasonlítható", "isCorrect": false}], "timeLimit": 15}, {"id": "4afd3739-5414-4aeb-bab4-7c753c9353f1", "text": "A nullánál kisebb számokat negatív számoknak nevezzük.", "type": "true-false", "options": [{"id": "b32ed8ea-152c-4565-b9a0-1a60282cd1c8", "text": "Igaz", "isCorrect": true}, {"id": "312793b9-bc78-4186-a128-73a94e2bd9be", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "10b2e79e-de99-494d-aac3-541a4b5a2c83", "text": "Mennyi (-10) + (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}]'::jsonb, true, NOW()),
('6984c6e3-091e-4f3a-be77-4920c3cc0118', '21feff02-016d-46e2-bb9d-c27495133b1b', '5. óra: Az egész számok szorzása', 'Negatív számokkal való szorzás, az előjelszabály megértése és alkalmazása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "e0a48913-e368-4829-8288-83b74585270d", "text": "Mi az előjelszabály két negatív szám szorzásakor? (- * -)", "type": "multiple-choice", "options": [{"id": "fe5f55e4-2eff-4232-b998-b69bb3ec8f80", "text": "Pozitív (+)", "isCorrect": true}, {"id": "f73695a0-1c76-48ae-8a0f-65b4907b60a5", "text": "Negatív (-)", "isCorrect": false}, {"id": "a05e62d2-b2f3-4913-959a-45bb8108c3fb", "text": "Mindig 0", "isCorrect": false}, {"id": "92b0e043-ab00-4c66-bbce-ea20c7164a21", "text": "Nem lehet megszorozni", "isCorrect": false}], "timeLimit": 15}, {"id": "b02b6e63-e35f-4718-9f15-30d98be3b5f7", "text": "Mennyi (-4) * (+5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-20"}, {"id": "8240d2a8-a97f-4d16-96ef-5a3eb7d8bda2", "text": "Mennyi (-6) * (-7)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "42"}, {"id": "0cca923b-3d27-41cc-a9c0-2dce9aebeda0", "text": "Egy pozitív és egy negatív szám szorzata mindig negatív.", "type": "true-false", "options": [{"id": "0eff57b9-e49e-47e2-bd51-a307fdf3c2e5", "text": "Igaz", "isCorrect": true}, {"id": "3e22ef40-dfdf-4238-858a-1bd8ab897a90", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fa087684-f671-4654-b3fc-61e5eff3ce8c", "text": "Mennyi (-3) * 0?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}, {"id": "292242ae-45e8-4305-a737-c2bb55b1febf", "text": "Ha három negatív számot szorzunk össze, a szorzat előjele negatív lesz.", "type": "true-false", "options": [{"id": "a776297c-31af-4d34-9f26-7510249bdafd", "text": "Igaz (- * - * - = -)", "isCorrect": true}, {"id": "bdaa6c89-f48e-4df1-93e2-dbacda910123", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "3f5af3c0-6956-4ef3-afd8-7c803ec56d76", "text": "Mennyi (-2) * (-3) * (-4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-24"}]'::jsonb, true, NOW()),
('47c7cf61-d2cf-4d08-9581-9f02e0c32b42', '21feff02-016d-46e2-bb9d-c27495133b1b', '6. óra: Gyakorlóóra: az egész számok szorzása', 'Több tényező előjelének meghatározása, szorzások gyakorlása.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "ab67c373-d44e-40a4-9f57-aa7004c5fe9d", "text": "Mennyi (-5) * (-2) * (+3)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "30"}, {"id": "998f818d-2c44-4586-860c-6aedf409e1a8", "text": "Ha egy szorzatban páros számú negatív tényező van, a szorzat előjele:", "type": "multiple-choice", "options": [{"id": "930fe38d-f6d4-4aac-831b-4765fbb6d480", "text": "Pozitív", "isCorrect": true}, {"id": "d0cffa2e-eff4-4d04-878b-c3ae294f21a9", "text": "Negatív", "isCorrect": false}, {"id": "f7fb648f-4160-45b3-8274-a032894e967b", "text": "Nulla", "isCorrect": false}, {"id": "050a0af7-9530-4729-a708-d37e5f3e982a", "text": "Változó", "isCorrect": false}], "timeLimit": 15}, {"id": "3a4693e2-1325-468c-a750-981844577013", "text": "Mennyi (-10) * (-10)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "100"}, {"id": "e82c0b1f-0081-4545-bf6a-0cd2b017bf6d", "text": "A 0-val való szorzás eredménye mindig 0.", "type": "true-false", "options": [{"id": "18facafd-ffd6-47e7-8ae4-d053c15f3663", "text": "Igaz", "isCorrect": true}, {"id": "edf7e275-7562-49ca-a51f-0f0cb87aa7ee", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "fcc7f922-e3cf-4754-a257-41899f4b798e", "text": "Mennyi (-1) * (+15)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-15"}, {"id": "b11af874-8298-4ae6-a243-b0472c988559", "text": "Mennyi a (-2) köbe ( (-2) * (-2) * (-2) )?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-8"}, {"id": "cdb07269-672b-4101-8875-d5f5023e74f1", "text": "Az írásbeli szorzáskor az előjelet a művelet végzésétől függetlenül, az előjelszabály szerint állapítjuk meg.", "type": "true-false", "options": [{"id": "e50f1a2c-cf2d-48cd-b869-b86ddef0e9a9", "text": "Igaz", "isCorrect": true}, {"id": "34c6c535-c2b0-48d2-990f-43c566b525ac", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}]'::jsonb, true, NOW()),
('9e47f6eb-3ae7-4215-9236-8c15916d88c6', '21feff02-016d-46e2-bb9d-c27495133b1b', '7. óra: Az egész számok osztása', 'Negatív osztandó, osztóval végzett műveletek algoritmusa, előjelszabály osztásnál.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "766d46bd-0efa-442a-91c3-51b5371b91a8", "text": "Mi az előjelszabály egész számok osztásakor?", "type": "multiple-choice", "options": [{"id": "e3c9af25-b594-430c-8aa1-3764982bebe3", "text": "Ugyanaz, mint a szorzásnál (+:+=+, -:-=+, +:-=-, -:+=-)", "isCorrect": true}, {"id": "4d133379-1ff3-4e0b-8417-dde9426e71f6", "text": "Mindig negatív", "isCorrect": false}, {"id": "624c0d0f-655c-4f91-8937-d2d70e44c7a3", "text": "Mindig pozitív", "isCorrect": false}, {"id": "1ff7c231-9af9-4742-a976-f92a46490732", "text": "Kivonást kell végezni", "isCorrect": false}], "timeLimit": 15}, {"id": "e73f99ad-c13b-41fa-bf81-a99a578c54d4", "text": "Mennyi (-20) : (+4)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-5"}, {"id": "fbe850b9-0bda-4fd8-90a3-5af1fc9a1e79", "text": "Mennyi (-36) : (-6)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "50437c9f-c47b-4dcb-8670-ebeeaf2937e5", "text": "Nullával osztani nem lehet a matematikában.", "type": "true-false", "options": [{"id": "ba5f3676-6a75-444f-a5d0-ffef20bcd208", "text": "Igaz", "isCorrect": true}, {"id": "1175531a-2514-421b-aea3-57510dba62b5", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "e2a50eaa-e9e8-4294-8af5-1bb98f4f645b", "text": "Mennyi (+50) : (-5)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-10"}, {"id": "f3737d5c-9ef7-4a99-8727-270abee00826", "text": "Ha a (-15)-öt elosztjuk (-3)-mal, az eredmény pozitív szám.", "type": "true-false", "options": [{"id": "21deecbf-bd69-4d76-86c0-7faab0abddb8", "text": "Igaz", "isCorrect": true}, {"id": "0e64bd3d-ac40-47be-a655-dee901f47815", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "f7727b37-7520-4db3-998f-e5f3ae2c5c68", "text": "Mennyi 0 : (-8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "0"}]'::jsonb, true, NOW()),
('2884d1dd-a214-4ed4-82eb-3506e87f2b35', '21feff02-016d-46e2-bb9d-c27495133b1b', '8. óra: Az egész számok osztásának gyakorlása', 'Írásbeli és fejben osztás gyakorlása negatív és pozitív számokkal.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "b4bfb4b9-1b28-4529-bbb4-4726a9d755c9", "text": "Mennyi (-100) : (-25)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "273affeb-7a1e-4230-aea0-581a2f16fe88", "text": "Mennyi (-48) : (+8)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-6"}, {"id": "1f5ef69a-0b6f-46cb-8ccf-0d9a9b65949b", "text": "Melyik egyenlet helyes?", "type": "multiple-choice", "options": [{"id": "86f13dbf-ac52-4b68-85ca-16358aa1baf1", "text": "(-18) : (-3) = 6", "isCorrect": true}, {"id": "e2ed6f1b-3b33-4a81-8c85-54bee2ed36de", "text": "(-18) : (-3) = -6", "isCorrect": false}, {"id": "f94ee957-e465-4907-91d7-6a8c2971339c", "text": "(-18) : (+3) = 6", "isCorrect": false}, {"id": "3770bb4d-779a-4b8b-be2c-fcee8d9991ad", "text": "(+18) : (-3) = 6", "isCorrect": false}], "timeLimit": 15}, {"id": "af5f1370-8748-4183-990c-93694e697130", "text": "A hányados ellenőrzése szorzással történik.", "type": "true-false", "options": [{"id": "7373f2e8-73bb-43e5-9285-863103a9a3a3", "text": "Igaz", "isCorrect": true}, {"id": "c365ba7e-fbcd-4cf2-8c04-4ac7c5d58907", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "4e087599-294c-4732-9401-757af06cd3ad", "text": "Mennyi (-81) : (+9)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "-9"}, {"id": "ca9ae88a-89e2-41ea-8c2f-21e62158282c", "text": "Ha két szám hányadosa pozitív, a két szám előjele azonos.", "type": "true-false", "options": [{"id": "89e6b66d-aa66-48c2-9985-418bb9a5db59", "text": "Igaz", "isCorrect": true}, {"id": "aeb9f1de-7b4b-4b27-a47e-36c6accf0811", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "796cdf14-49af-411d-a315-344a0979e9d7", "text": "Mennyi (-144) : (-12)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "12"}]'::jsonb, true, NOW()),
('c5b30346-6804-42ab-ba95-c0bbcfff51dc', '21feff02-016d-46e2-bb9d-c27495133b1b', '9. óra: Hány eset van? Számoljuk össze!', 'Összeszámlálás fagráffal (ágrajz), táblázattal, rendszerezett felsorolással.', 'Matematika', '6. osztály', 'Egész számok, oszthatóság', '[{"id": "f1305067-7661-442c-93e6-b7a3a7868eda", "text": "Milyen eszközt használhatunk az összes lehetőség rendszerezett szemléltetésére?", "type": "multiple-choice", "options": [{"id": "e12b3f60-c32b-461d-9bbb-1c74a3b06f5b", "text": "Fagráfot (ágrajzot) és táblázatot", "isCorrect": true}, {"id": "142492bc-44f8-4704-9bda-5e8498fc6dca", "text": "Szögmérőt", "isCorrect": false}, {"id": "56d9fabd-0d07-45eb-a100-42e4b0c5a9b6", "text": "Körzőt", "isCorrect": false}, {"id": "62ad6e7d-2290-43d3-ab41-63921f0ce258", "text": "Vonalzót", "isCorrect": false}], "timeLimit": 15}, {"id": "05833824-0e8e-4295-8939-c797379942fe", "text": "Hányféleképpen ülhet le 2 gyerek (Peti és Kati) két egymás melletti székre?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}, {"id": "ac3f71c3-36f6-4b5b-a19c-13662df401b7", "text": "Hány különböző 2 jegyű szám képezhető az 1 és 2 számjegyekből (számjegyismétléssel)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "4"}, {"id": "c97bf354-2b68-40f2-9591-f47bd5a18b6e", "text": "A rendszerezett felsorolás segít abban, hogy egyetlen lehetőséget se hagyjunk ki.", "type": "true-false", "options": [{"id": "1ee76839-7cf9-44af-9622-fecaae92e01b", "text": "Igaz", "isCorrect": true}, {"id": "99f7c1ae-0878-4d80-90d6-e10f73a3a59d", "text": "Hamis", "isCorrect": false}], "timeLimit": 15}, {"id": "48ede479-633b-4569-8e29-d67dde6139b8", "text": "Hányféleképpen választhatunk ki 3 póló és 2 nadrág közül egy ruhakészletet?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "6"}, {"id": "e0fbd843-84b2-4a5a-ae48-7b5b868fe07e", "text": "A kombinatorikai feladatoknál a sorrend mindig számít.", "type": "true-false", "options": [{"id": "e13c2b21-9547-48d9-b913-992b4735dbba", "text": "Igaz", "isCorrect": false}, {"id": "0e32e093-8fc2-43ac-89cd-a390759f95c0", "text": "Hamis (van ahol számít, van ahol nem)", "isCorrect": true}], "timeLimit": 15}, {"id": "044b0f93-35e5-4d29-874d-b2d65feec953", "text": "Hány lapja van egy érmének (kimenetelek száma)?", "type": "text-input", "options": [], "timeLimit": 20, "correctAnswer": "2"}]'::jsonb, true, NOW()),
